{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "Whether commercially acceptable depends on warranty coverage, diligence, insurance and the other limitations; it should not be accepted in isolation."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "seek a lower de minimis, aggregation of related claims, and a **tipping basket**"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek at least **24 months for general warranties**, with longer, separate regimes below."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "separate fundamental warranties covering authority, ownership, all issued shares, absence of encumbrances and rights to acquire shares."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Include express carve-outs for fraud, fraudulent misrepresentation and deliberate concealment by the Seller and appropriately defined relevant persons."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket disclosure of public records and documents merely referred to elsewhere."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Prefer no buyer-knowledge exclusion; if unavoidable, restrict it to actual knowledge of named deal-team members"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Nor should delivery of a conditional consent automatically satisfy the condition."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Riverlark payout and effective release arrangements at Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Expressly allocate the agreed seller-borne cost through the price adjustment or funds flow, with an indemnity for uncovered amounts."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "If residual exposure remains, require a broader specific indemnity for losses arising from the pre-Completion ownership/payment defect."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity for the pre-Completion incident, including reasonable investigation, remediation and third-party claim costs"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "If they are necessary post-Completion operating services, ordinary operating treatment may be appropriate."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "allocate limitations expressly by claim category."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is evidence of registered ownership, not complete title diligence."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Do not accept the assertion that tax and IP are “settled” under the general regime."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

